const fs = require("fs");
const path = require("path");
const { execSync } = require("child_process");

console.log("--> Restaurando codigo fonte mais recente do AI Studio...");
for (const [filePath, content] of Object.entries(payload.files)) {
    const dir = path.dirname(filePath);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(filePath, content, "utf-8");
    console.log(" Atualizado: " + filePath);
}

if (!fs.existsSync("public/Tratadas")) fs.mkdirSync("public/Tratadas", { recursive: true });
fs.writeFileSync("public/Tratadas/MONICA 3.jpg", Buffer.from(payload.monica3, "base64"));
fs.writeFileSync("public/Tratadas/MARCOS 3.jpg", Buffer.from(payload.marcos3, "base64"));

console.log("\n--> Executando Git e Deploy para Surge...");
try {
    execSync("git add .", { stdio: "inherit" });
    execSync("git commit -m \"feat: sincronizar versao completa do AI Studio (ditafone 1990s + novas fotos)\"", { stdio: "inherit" });
    execSync("git push origin master", { stdio: "inherit" });
    execSync("npm run deploy", { stdio: "inherit" });
    console.log("\n SUCESSO! O projeto foi atualizado no GitHub e publicado no Surge!");
} catch (err) {
    console.error("Erro durante o deploy:", err.message);
}
